package com.ssafy.yumyumcoach.manager;

import com.ssafy.yumyumcoach.domain.*;
import com.ssafy.yumyumcoach.repository.DataRepository;
import com.ssafy.yumyumcoach.util.*;
import java.util.*;
public class CommunityManager { private final DataRepository repo; public CommunityManager(DataRepository r){repo=r;} public List<Post> posts(){return List.copyOf(repo.posts());} public Post createPost(String user,String board,String title,String content){Post p=new Post(repo.nextPostId(),user,board,title,content);repo.posts().add(p);repo.save();return p;} private Post post(long id){return repo.posts().stream().filter(p->p.getId()==id).findFirst().orElseThrow(()->new IllegalArgumentException("게시글이 없습니다."));} public void updatePost(long id,String user,String t,String c){Post p=post(id);owner(p.getAuthorId(),user);p.update(t,c);repo.save();} public void deletePost(long id,String user){Post p=post(id);owner(p.getAuthorId(),user);repo.comments().removeIf(c->c.getPostId()==id);repo.posts().remove(p);repo.save();} public PerformanceMetrics<List<Post>> search(String keyword){return SearchAlgorithms.kmpSearch(repo.posts(),p->p.getTitle()+" "+p.getContent(),keyword);} public Comment createComment(long postId,String user,String content){post(postId);Comment c=new Comment(repo.nextCommentId(),postId,user,content);repo.comments().add(c);repo.save();return c;} public List<Comment> comments(long postId){return repo.comments().stream().filter(c->c.getPostId()==postId).toList();} public void updateComment(long id,String user,String content){Comment c=repo.comments().stream().filter(x->x.getId()==id).findFirst().orElseThrow(()->new IllegalArgumentException("댓글이 없습니다."));owner(c.getAuthorId(),user);c.update(content);repo.save();} public void deleteComment(long id,String user){Comment c=repo.comments().stream().filter(x->x.getId()==id).findFirst().orElseThrow(()->new IllegalArgumentException("댓글이 없습니다."));owner(c.getAuthorId(),user);repo.comments().remove(c);repo.save();} private void owner(String owner,String user){if(!owner.equals(user))throw new IllegalArgumentException("본인이 작성한 항목만 변경할 수 있습니다.");} }
